alter table aip."site_weather" add column if not exists "wind_kmh" integer;
alter table aip."site_weather" add column if not exists "gust_kmh" integer;
alter table aip."site_weather" add column if not exists "lightning_risk" text;
alter table aip."site_weather" add column if not exists "temperature_c" integer;
alter table aip."site_weather" add column if not exists "visibility_km" integer;
alter table aip."site_weather" add column if not exists "work_at_height_status" text;
alter table aip."site_weather" add column if not exists "outdoor_electrical_status" text;
alter table aip."site_weather" add column if not exists "access_status" text;
alter table aip."site_weather" add column if not exists "freshness_status" text;
alter table aip."site_weather" add column if not exists "source_system_id" uuid references aip."ref_source_system"(id);
