alter table aip."site_weather" add column if not exists "evidence_id" text;
alter table aip."site_weather" add column if not exists "source_ordinal" integer;
drop trigger if exists t_ref_guard on aip."site_weather";
create trigger t_ref_guard before insert or update on aip."site_weather" for each row execute function aip.ref_tenant_guard('source_system_id', 'ref_source_system');
-- Record link: One hop of the decision loop between records of different modules (finding → work order, intervention → work order, …).
select aip.create_master_table('record_link', 'Record link', $cols$"from_entity" text, "from_code" text, "link_type" text, "to_entity" text, "to_code" text, "linked_at" timestamp without time zone, "status" text, "source_record" text, "response_time_hours" numeric(24,2)$cols$, null, array['planner','admin']);
alter table aip."record_link" add column if not exists "from_entity" text;
alter table aip."record_link" add column if not exists "from_code" text;
alter table aip."record_link" add column if not exists "link_type" text;
alter table aip."record_link" add column if not exists "to_entity" text;
alter table aip."record_link" add column if not exists "to_code" text;
alter table aip."record_link" add column if not exists "linked_at" timestamp without time zone;
alter table aip."record_link" add column if not exists "status" text;
alter table aip."record_link" add column if not exists "source_record" text;
alter table aip."record_link" add column if not exists "response_time_hours" numeric(24,2);
drop trigger if exists t_ref_guard on aip."record_link";

