-- Code views: references as business codes (security_invoker, so RLS applies to the caller).
drop view if exists aip."v_alert";
create view aip."v_alert" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "asset", r1.code as "site", m."component", m."alert_timestamp", m."model", m."risk_score", m."rul_days", m."confidence_pct", m."risk_tier", r9.code as "status", m."evidence_summary", m."data_basis", m."source_ordinal", m.is_active, m.row_version, m.updated_at
from aip."alert" m
left join aip."asset" r0 on r0.id = m."asset_id"
left join aip."site" r1 on r1.id = m."site_id"
left join aip."ref_status" r9 on r9.id = m."status_id";
grant select on aip."v_alert" to authenticated, service_role;
drop view if exists aip."v_recommendation";
create view aip."v_recommendation" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "alert", r1.code as "asset", r2.code as "site", m."risk_score", m."rul_days", m."recommended_action", m."cost_now", m."cost_if_deferred", m."cost_avoided", m."confidence_pct", r10.code as "status", m."rationale", m."source_ordinal", m.currency, m.is_active, m.row_version, m.updated_at
from aip."recommendation" m
left join aip."alert" r0 on r0.id = m."alert_id"
left join aip."asset" r1 on r1.id = m."asset_id"
left join aip."site" r2 on r2.id = m."site_id"
left join aip."ref_status" r10 on r10.id = m."status_id";
grant select on aip."v_recommendation" to authenticated, service_role;
drop view if exists aip."v_work_order";
create view aip."v_work_order" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "maintenance_type", r1.code as "asset", r2.code as "site", m."description", r4.code as "priority", r5.code as "status", m."created_date", m."sla_due", m."sla_hours", m."actual_resolution_hours", m."sla_result", m."source_record", m."estimated_cost", r13.code as "technician", m."assigned_crew", m."pm_frequency_days", m."pm_due_date", m."actual_pm_completion_date", m."pm_compliance_tolerance_days", m."pm_compliance_result", m."pm_overdue_days", r21.code as "alert", r22.code as "required_part", m."required_part_qty", r24.code as "pv_module", m."data_basis", m."source_ordinal", m.currency, m.is_active, m.row_version, m.updated_at
from aip."work_order" m
left join aip."ref_maintenance_type" r0 on r0.id = m."maintenance_type_id"
left join aip."asset" r1 on r1.id = m."asset_id"
left join aip."site" r2 on r2.id = m."site_id"
left join aip."ref_priority" r4 on r4.id = m."priority_id"
left join aip."ref_status" r5 on r5.id = m."status_id"
left join aip."technician" r13 on r13.id = m."technician_id"
left join aip."alert" r21 on r21.id = m."alert_id"
left join aip."part" r22 on r22.id = m."required_part_id"
left join aip."pv_module" r24 on r24.id = m."pv_module_id";
grant select on aip."v_work_order" to authenticated, service_role;
drop view if exists aip."v_event";
create view aip."v_event" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, m."incident_id", r1.code as "site", r2.code as "asset", m."event_date_time", r4.code as "event_type", r5.code as "severity", m."alarm_code", m."weather_context", m."generation_loss_mwh", m."revenue_impact", r10.code as "status", r11.code as "source_system", m."event_timestamp", r13.code as "pv_module", m."classified_failure", m."source_ordinal", m.currency, m.is_active, m.row_version, m.updated_at
from aip."event" m
left join aip."site" r1 on r1.id = m."site_id"
left join aip."asset" r2 on r2.id = m."asset_id"
left join aip."ref_event_type" r4 on r4.id = m."event_type_id"
left join aip."ref_severity" r5 on r5.id = m."severity_id"
left join aip."ref_status" r10 on r10.id = m."status_id"
left join aip."ref_source_system" r11 on r11.id = m."source_system_id"
left join aip."pv_module" r13 on r13.id = m."pv_module_id";
grant select on aip."v_event" to authenticated, service_role;
drop view if exists aip."v_rca_case";
create view aip."v_rca_case" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "event", r1.code as "site", r2.code as "asset", r3.code as "event_type", r4.code as "severity", m."event_time", m."cause_name", m."reference_id", m."verification_method", m."confidence_pct", r10.code as "status", m."engineer_approval", m."oem_recorded", m."model_recorded", m."source_ordinal", m.is_active, m.row_version, m.updated_at
from aip."rca_case" m
left join aip."event" r0 on r0.id = m."event_id"
left join aip."site" r1 on r1.id = m."site_id"
left join aip."asset" r2 on r2.id = m."asset_id"
left join aip."ref_event_type" r3 on r3.id = m."event_type_id"
left join aip."ref_severity" r4 on r4.id = m."severity_id"
left join aip."ref_status" r10 on r10.id = m."status_id";
grant select on aip."v_rca_case" to authenticated, service_role;
drop view if exists aip."v_rca_evidence";
create view aip."v_rca_evidence" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "event", r1.code as "rca_case", r2.code as "site", r3.code as "asset", m."signal", m."actual_value", m."peer_baseline", r7.code as "unit", m."deviation_pct", r9.code as "source_system", m."evidence_role", m."engineering_interpretation", m."source_ordinal", m.is_active, m.row_version, m.updated_at
from aip."rca_evidence" m
left join aip."event" r0 on r0.id = m."event_id"
left join aip."rca_case" r1 on r1.id = m."rca_case_id"
left join aip."site" r2 on r2.id = m."site_id"
left join aip."asset" r3 on r3.id = m."asset_id"
left join aip."ref_unit" r7 on r7.id = m."unit_id"
left join aip."ref_source_system" r9 on r9.id = m."source_system_id";
grant select on aip."v_rca_evidence" to authenticated, service_role;
drop view if exists aip."v_vision_inspection";
create view aip."v_vision_inspection" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "site", m."inspection_date_time", m."inspection_type", m."device_id", m."panels_inspected", m."images_captured", m."coverage_pct", m."weather", m."flight_altitude_m", m."inspection_status", m."inspector", r11.code as "asset", m."data_basis", m."source_ordinal", m.is_active, m.row_version, m.updated_at
from aip."vision_inspection" m
left join aip."site" r0 on r0.id = m."site_id"
left join aip."asset" r11 on r11.id = m."asset_id";
grant select on aip."v_vision_inspection" to authenticated, service_role;
drop view if exists aip."v_vision_finding";
create view aip."v_vision_finding" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "inspection", r1.code as "site", r2.code as "asset", r3.code as "defect_type", m."detection_mode", m."confidence_pct", r6.code as "severity", r7.code as "status", m."estimated_loss_k_wh_day", m."annual_revenue_risk", m."recommended_action", r11.code as "work_order", m."affected_area_sqm", m."physical_location", m."inspection_date", m."inspector", r16.code as "pv_module", m."classified_failure", m."data_basis", m."source_ordinal", m.currency, m.is_active, m.row_version, m.updated_at
from aip."vision_finding" m
left join aip."vision_inspection" r0 on r0.id = m."inspection_id"
left join aip."site" r1 on r1.id = m."site_id"
left join aip."asset" r2 on r2.id = m."asset_id"
left join aip."ref_defect_code" r3 on r3.id = m."defect_type_id"
left join aip."ref_severity" r6 on r6.id = m."severity_id"
left join aip."ref_status" r7 on r7.id = m."status_id"
left join aip."work_order" r11 on r11.id = m."work_order_id"
left join aip."pv_module" r16 on r16.id = m."pv_module_id";
grant select on aip."v_vision_finding" to authenticated, service_role;
drop view if exists aip."v_warranty_claim";
create view aip."v_warranty_claim" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "warranty", m."incident_id", r2.code as "asset", r3.code as "site", m."claim_date", m."failure_event_id", r6.code as "status", m."claimed_amount", m."approved_amount", m."days_open", m."evidence_completeness_pct", m."notice_deadline", m."oem_response_date", m."rejection_reason", m."next_action", r15.code as "work_order", r16.code as "pv_module", m."data_basis", m."source_ordinal", m.currency, m.is_active, m.row_version, m.updated_at
from aip."warranty_claim" m
left join aip."warranty_contract" r0 on r0.id = m."warranty_id"
left join aip."asset" r2 on r2.id = m."asset_id"
left join aip."site" r3 on r3.id = m."site_id"
left join aip."ref_status" r6 on r6.id = m."status_id"
left join aip."work_order" r15 on r15.id = m."work_order_id"
left join aip."pv_module" r16 on r16.id = m."pv_module_id";
grant select on aip."v_warranty_claim" to authenticated, service_role;
drop view if exists aip."v_pm_plan";
create view aip."v_pm_plan" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "asset", m."task", m."frequency_days", m."last_done", m."next_due", m."overdue_days", m."standard_labour_hours", r7.code as "primary_part", r8.code as "required_skill", r9.code as "site", m."data_basis", m."source_ordinal", m.is_active, m.row_version, m.updated_at
from aip."pm_plan" m
left join aip."asset" r0 on r0.id = m."asset_id"
left join aip."part" r7 on r7.id = m."primary_part_id"
left join aip."ref_skill" r8 on r8.id = m."required_skill_id"
left join aip."site" r9 on r9.id = m."site_id";
grant select on aip."v_pm_plan" to authenticated, service_role;
drop view if exists aip."v_cbm_assessment";
create view aip."v_cbm_assessment" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "site", r1.code as "asset", r2.code as "failure_mode", r3.code as "observed_defect", m."primary_condition", m."source_mode", m."latest_evidence_time", m."freshness_class", m."max_deviation_pct", m."evidence_count", m."corroboration_count", m."condition_severity", m."risk_context", m."evidence_sufficiency_pct", m."engineering_physics_fit_pct", m."confidence_pct", r16.code as "priority", m."condition_state", m."recommended_action", m."governance_class", m."approval_role", m."source_module", m."source_record_id", m."target_view", m."work_order_code", m."reference_id", m."verification_method", m."decision_basis", m."source_ordinal", m.is_active, m.row_version, m.updated_at
from aip."cbm_assessment" m
left join aip."site" r0 on r0.id = m."site_id"
left join aip."asset" r1 on r1.id = m."asset_id"
left join aip."ref_failure_mode" r2 on r2.id = m."failure_mode_id"
left join aip."ref_defect_code" r3 on r3.id = m."observed_defect_id"
left join aip."ref_priority" r16 on r16.id = m."priority_id";
grant select on aip."v_cbm_assessment" to authenticated, service_role;
drop view if exists aip."v_condition_evidence";
create view aip."v_condition_evidence" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "assessment", r1.code as "site", r2.code as "asset", m."evidence_source", m."arrival_mode", m."source_module", m."target_view", m."source_record_id", m."observed_time", m."signal_name", m."observed_value", m."baseline_or_peer", r12.code as "unit", m."deviation_pct", m."evidence_role", m."quality_pct", m."engineering_interpretation", m."freshness_label", m."source_ordinal", m.is_active, m.row_version, m.updated_at
from aip."condition_evidence" m
left join aip."cbm_assessment" r0 on r0.id = m."assessment_id"
left join aip."site" r1 on r1.id = m."site_id"
left join aip."asset" r2 on r2.id = m."asset_id"
left join aip."ref_unit" r12 on r12.id = m."unit_id";
grant select on aip."v_condition_evidence" to authenticated, service_role;
drop view if exists aip."v_part_requirement";
create view aip."v_part_requirement" with (security_invoker = true) as
select m.id, m.tenant_id, m.code, r0.code as "intervention", r1.code as "work_order", m."decision_id", r3.code as "site", r4.code as "asset", r5.code as "maintenance_type", r6.code as "part", m."required_qty", m."required_by", m."status", m."requirement_source", m."source_record_id", m."as_of", m."source_ordinal", m.is_active, m.row_version, m.updated_at
from aip."part_requirement" m
left join aip."intervention" r0 on r0.id = m."intervention_id"
